window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-858dca070df682cf"]={"versions": [{"id": "FIG-858dca070df682cf", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells im AUTOSAR Diagnostic Extract (TPS Diagnostic Extract Template). Das Diagramm stellt die Vererbungshierarchie der Diagnose-Mapping-Elemente (DiagnosticMapping) innerhalb der AUTOSAR-Modellstruktur dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst folgende Modellelemente und Generalisierungsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>ARElement</code> / <code>DiagnosticCommonElement</code>: Abstrakte Basiselemente bzw. Paketelemente an der Spitze der dargestellten Vererbungshierarchie.</li>\n<li><code>DiagnosticMapping</code> (kursiv/abstrakt): Spezialisiert <code>DiagnosticCommonElement</code>. Dient als Basisklasse für Zuordnungsdefinitionen im Diagnose-Metamodell.</li>\n<li><code>DiagnosticSwMapping</code> (kursiv/abstrakt): Spezialisiert <code>DiagnosticMapping</code>. Dient als gemeinsame Basisklasse für Software-spezifische Diagnose-Port- und Funktions-Mappings.</li>\n<li>Konkrete Subklassen von <code>DiagnosticSwMapping</code>:</li>\n<li><code>DiagnosticEventPortMapping</code>: Mapping für Diagnose-Event-Ports.</li>\n<li><code>DiagnosticEnableConditionPortMapping</code>: Mapping für Enable-Condition-Ports.</li>\n<li><code>DiagnosticOperationCyclePortMapping</code>: Mapping für Betriebszyklus-Ports (Operation Cycle).</li>\n<li><code>DiagnosticStorageConditionPortMapping</code>: Mapping für Speicherbedingungs-Ports (Storage Condition).</li>\n<li><code>DiagnosticFimFunctionMapping</code>: Mapping für Function-Inhibition-Manager-Funktionen (FiM).</li>\n</ul>\n<p class=\"fig-p\">Alle abgeleiteten Klassen erben über geschlossene, nicht ausgefüllte Dreieckspfeile (UML-Generalisierung) von ihren jeweiligen Basisklassen. Attribute, Assoziationen oder Methoden sind in den Klassenboxen nicht detailliert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodell-Klassenhierarchie; es wird kein dynamisches Laufzeitverhalten, kein Sequenzablauf und kein Zustandsübergang dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die normative Vererbungsstruktur für Mappings im AUTOSAR Diagnostic Extract Template. Modellierer und Werkzeugentwickler müssen sicherstellen, dass spezifische Mapping-Elemente wie <code>DiagnosticEventPortMapping</code>, <code>DiagnosticEnableConditionPortMapping</code>, <code>DiagnosticOperationCyclePortMapping</code>, <code>DiagnosticStorageConditionPortMapping</code> und <code>DiagnosticFimFunctionMapping</code> als Spezialisierungen von <code>DiagnosticSwMapping</code> abgeleitet sind und die Eigenschaften von <code>DiagnosticMapping</code> sowie <code>ARElement</code> / <code>DiagnosticCommonElement</code> erben.</p>"}, {"id": "FIG-702d7cf53582d00d", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells im AUTOSAR Diagnostic Extract (TPS Diagnostic Extract Template). Das Diagramm stellt die Vererbungshierarchie der Diagnose-Mapping-Elemente (DiagnosticMapping) innerhalb der AUTOSAR-Modellstruktur dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst folgende Modellelemente und Generalisierungsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>ARElement</code> / <code>DiagnosticCommonElement</code>: Abstrakte Basiselemente bzw. Paketelemente an der Spitze der dargestellten Vererbungshierarchie.</li>\n<li><code>DiagnosticMapping</code> (kursiv/abstrakt): Spezialisiert <code>DiagnosticCommonElement</code>. Dient als Basisklasse für Zuordnungsdefinitionen im Diagnose-Metamodell.</li>\n<li><code>DiagnosticSwMapping</code> (kursiv/abstrakt): Spezialisiert <code>DiagnosticMapping</code>. Dient als gemeinsame Basisklasse für Software-spezifische Diagnose-Port- und Funktions-Mappings.</li>\n<li>Konkrete Subklassen von <code>DiagnosticSwMapping</code>:</li>\n<li><code>DiagnosticEventPortMapping</code>: Mapping für Diagnose-Event-Ports.</li>\n<li><code>DiagnosticEnableConditionPortMapping</code>: Mapping für Enable-Condition-Ports.</li>\n<li><code>DiagnosticOperationCyclePortMapping</code>: Mapping für Betriebszyklus-Ports (Operation Cycle).</li>\n<li><code>DiagnosticStorageConditionPortMapping</code>: Mapping für Speicherbedingungs-Ports (Storage Condition).</li>\n<li><code>DiagnosticFimFunctionMapping</code>: Mapping für Function-Inhibition-Manager-Funktionen (FiM).</li>\n</ul>\n<p class=\"fig-p\">Alle abgeleiteten Klassen erben über geschlossene, nicht ausgefüllte Dreieckspfeile (UML-Generalisierung) von ihren jeweiligen Basisklassen. Attribute, Assoziationen oder Methoden sind in den Klassenboxen nicht detailliert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodell-Klassenhierarchie; es wird kein dynamisches Laufzeitverhalten, kein Sequenzablauf und kein Zustandsübergang dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die normative Vererbungsstruktur für Mappings im AUTOSAR Diagnostic Extract Template. Modellierer und Werkzeugentwickler müssen sicherstellen, dass spezifische Mapping-Elemente wie <code>DiagnosticEventPortMapping</code>, <code>DiagnosticEnableConditionPortMapping</code>, <code>DiagnosticOperationCyclePortMapping</code>, <code>DiagnosticStorageConditionPortMapping</code> und <code>DiagnosticFimFunctionMapping</code> als Spezialisierungen von <code>DiagnosticSwMapping</code> abgeleitet sind und die Eigenschaften von <code>DiagnosticMapping</code> sowie <code>ARElement</code> / <code>DiagnosticCommonElement</code> erben.</p>"}, {"id": "FIG-2f975ccb5cf0ae6b", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells im AUTOSAR Diagnostic Extract (TPS Diagnostic Extract Template). Das Diagramm stellt die Vererbungshierarchie der Diagnose-Mapping-Elemente (DiagnosticMapping) innerhalb der AUTOSAR-Modellstruktur dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst folgende Modellelemente und Generalisierungsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>ARElement</code> / <code>DiagnosticCommonElement</code>: Abstrakte Basiselemente bzw. Paketelemente an der Spitze der dargestellten Vererbungshierarchie.</li>\n<li><code>DiagnosticMapping</code> (kursiv/abstrakt): Spezialisiert <code>DiagnosticCommonElement</code>. Dient als Basisklasse für Zuordnungsdefinitionen im Diagnose-Metamodell.</li>\n<li><code>DiagnosticSwMapping</code> (kursiv/abstrakt): Spezialisiert <code>DiagnosticMapping</code>. Dient als gemeinsame Basisklasse für Software-spezifische Diagnose-Port- und Funktions-Mappings.</li>\n<li>Konkrete Subklassen von <code>DiagnosticSwMapping</code>:</li>\n<li><code>DiagnosticEventPortMapping</code>: Mapping für Diagnose-Event-Ports.</li>\n<li><code>DiagnosticEnableConditionPortMapping</code>: Mapping für Enable-Condition-Ports.</li>\n<li><code>DiagnosticOperationCyclePortMapping</code>: Mapping für Betriebszyklus-Ports (Operation Cycle).</li>\n<li><code>DiagnosticStorageConditionPortMapping</code>: Mapping für Speicherbedingungs-Ports (Storage Condition).</li>\n<li><code>DiagnosticFimFunctionMapping</code>: Mapping für Function-Inhibition-Manager-Funktionen (FiM).</li>\n</ul>\n<p class=\"fig-p\">Alle abgeleiteten Klassen erben über geschlossene, nicht ausgefüllte Dreieckspfeile (UML-Generalisierung) von ihren jeweiligen Basisklassen. Attribute, Assoziationen oder Methoden sind in den Klassenboxen nicht detailliert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodell-Klassenhierarchie; es wird kein dynamisches Laufzeitverhalten, kein Sequenzablauf und kein Zustandsübergang dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die normative Vererbungsstruktur für Mappings im AUTOSAR Diagnostic Extract Template. Modellierer und Werkzeugentwickler müssen sicherstellen, dass spezifische Mapping-Elemente wie <code>DiagnosticEventPortMapping</code>, <code>DiagnosticEnableConditionPortMapping</code>, <code>DiagnosticOperationCyclePortMapping</code>, <code>DiagnosticStorageConditionPortMapping</code> und <code>DiagnosticFimFunctionMapping</code> als Spezialisierungen von <code>DiagnosticSwMapping</code> abgeleitet sind und die Eigenschaften von <code>DiagnosticMapping</code> sowie <code>ARElement</code> / <code>DiagnosticCommonElement</code> erben.</p>"}, {"id": "FIG-a489fddcceb2a762", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells im AUTOSAR Diagnostic Extract (TPS Diagnostic Extract Template). Das Diagramm stellt die Vererbungshierarchie der Diagnose-Mapping-Elemente (DiagnosticMapping) innerhalb der AUTOSAR-Modellstruktur dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst folgende Modellelemente und Generalisierungsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>ARElement</code> / <code>DiagnosticCommonElement</code>: Abstrakte Basiselemente bzw. Paketelemente an der Spitze der dargestellten Vererbungshierarchie.</li>\n<li><code>DiagnosticMapping</code> (kursiv/abstrakt): Spezialisiert <code>DiagnosticCommonElement</code>. Dient als Basisklasse für Zuordnungsdefinitionen im Diagnose-Metamodell.</li>\n<li><code>DiagnosticSwMapping</code> (kursiv/abstrakt): Spezialisiert <code>DiagnosticMapping</code>. Dient als gemeinsame Basisklasse für Software-spezifische Diagnose-Port- und Funktions-Mappings.</li>\n<li>Konkrete Subklassen von <code>DiagnosticSwMapping</code>:</li>\n<li><code>DiagnosticEventPortMapping</code>: Mapping für Diagnose-Event-Ports.</li>\n<li><code>DiagnosticEnableConditionPortMapping</code>: Mapping für Enable-Condition-Ports.</li>\n<li><code>DiagnosticOperationCyclePortMapping</code>: Mapping für Betriebszyklus-Ports (Operation Cycle).</li>\n<li><code>DiagnosticStorageConditionPortMapping</code>: Mapping für Speicherbedingungs-Ports (Storage Condition).</li>\n<li><code>DiagnosticFimFunctionMapping</code>: Mapping für Function-Inhibition-Manager-Funktionen (FiM).</li>\n</ul>\n<p class=\"fig-p\">Alle abgeleiteten Klassen erben über geschlossene, nicht ausgefüllte Dreieckspfeile (UML-Generalisierung) von ihren jeweiligen Basisklassen. Attribute, Assoziationen oder Methoden sind in den Klassenboxen nicht detailliert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodell-Klassenhierarchie; es wird kein dynamisches Laufzeitverhalten, kein Sequenzablauf und kein Zustandsübergang dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die normative Vererbungsstruktur für Mappings im AUTOSAR Diagnostic Extract Template. Modellierer und Werkzeugentwickler müssen sicherstellen, dass spezifische Mapping-Elemente wie <code>DiagnosticEventPortMapping</code>, <code>DiagnosticEnableConditionPortMapping</code>, <code>DiagnosticOperationCyclePortMapping</code>, <code>DiagnosticStorageConditionPortMapping</code> und <code>DiagnosticFimFunctionMapping</code> als Spezialisierungen von <code>DiagnosticSwMapping</code> abgeleitet sind und die Eigenschaften von <code>DiagnosticMapping</code> sowie <code>ARElement</code> / <code>DiagnosticCommonElement</code> erben.</p>"}, {"id": "FIG-0231ad845f639cd5", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells im AUTOSAR Diagnostic Extract (TPS Diagnostic Extract Template). Das Diagramm stellt die Vererbungshierarchie der Diagnose-Mapping-Elemente (DiagnosticMapping) innerhalb der AUTOSAR-Modellstruktur dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst folgende Modellelemente und Generalisierungsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>ARElement</code> / <code>DiagnosticCommonElement</code>: Abstrakte Basiselemente bzw. Paketelemente an der Wurzel der dargestellten Hierarchie.</li>\n<li><code>DiagnosticMapping</code> (kursiv/abstrakt): Spezialisiert <code>DiagnosticCommonElement</code> über eine horizontale Generalisierungsbeziehung.</li>\n<li><code>DiagnosticSwMapping</code> (kursiv/abstrakt): Spezialisiert <code>DiagnosticMapping</code> über eine horizontale Generalisierungsbeziehung.</li>\n<li>Konkrete Subklassen von <code>DiagnosticSwMapping</code>:</li>\n<li><code>DiagnosticEventPortMapping</code>: Mapping für Diagnose-Event-Ports.</li>\n<li><code>DiagnosticEnableConditionPortMapping</code>: Mapping für Enable-Condition-Ports.</li>\n<li><code>DiagnosticOperationCyclePortMapping</code>: Mapping für Betriebszyklus-Ports (Operation Cycle).</li>\n<li><code>DiagnosticStorageConditionPortMapping</code>: Mapping für Speicherbedingungs-Ports (Storage Condition).</li>\n<li><code>DiagnosticFimFunctionMapping</code>: Mapping für Function-Inhibition-Manager-Funktionen (FiM).</li>\n</ul>\n<p class=\"fig-p\">Alle abgeleiteten Klassen erben über geschlossene, nicht ausgefüllte Dreieckspfeile (UML-Generalisierung). Die oberen drei Klassen (<code>ARElement</code> / <code>DiagnosticCommonElement</code>, <code>DiagnosticMapping</code>, <code>DiagnosticSwMapping</code>) sind horizontal nebeneinander angeordnet, während die abgeleiteten Mapping-Klassen darunter platziert sind. Attribute, Assoziationen oder Methoden sind in den Klassenboxen nicht detailliert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodell-Klassenhierarchie; es wird kein dynamisches Laufzeitverhalten, kein Sequenzablauf und kein Zustandsübergang dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die normative Vererbungsstruktur für Mappings im AUTOSAR Diagnostic Extract Template. Modellierer und Werkzeugentwickler müssen sicherstellen, dass spezifische Mapping-Elemente wie <code>DiagnosticEventPortMapping</code>, <code>DiagnosticEnableConditionPortMapping</code>, <code>DiagnosticOperationCyclePortMapping</code>, <code>DiagnosticStorageConditionPortMapping</code> und <code>DiagnosticFimFunctionMapping</code> als Spezialisierungen von <code>DiagnosticSwMapping</code> abgeleitet sind und die Eigenschaften von <code>DiagnosticMapping</code> sowie <code>ARElement</code> / <code>DiagnosticCommonElement</code> erben.</p>"}], "trans": [{"from": "FIG-858dca070df682cf", "to": "FIG-702d7cf53582d00d", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-702d7cf53582d00d", "to": "FIG-2f975ccb5cf0ae6b", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-2f975ccb5cf0ae6b", "to": "FIG-a489fddcceb2a762", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-a489fddcceb2a762", "to": "FIG-0231ad845f639cd5", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Diagrammlayout: Die zuvor vertikal übereinander angeordneten Klassen ARElement/DiagnosticCommonElement, DiagnosticMapping und DiagnosticSwMapping sind nun horizontal nebeneinander angeordnet, wodurch sich die Vererbungspfeile zwischen ihnen von vertikal auf horizontal nach links gerichtet ändern.</li>\n</ul>"}]};
